BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE prospect_status AS ENUM ('work_now','light_research','suppress');
CREATE TYPE review_status AS ENUM ('needs_review','changes_requested','approved_for_send_prep');
CREATE TYPE job_status AS ENUM ('queued','running','partial','succeeded','failed','canceled','blocked');
CREATE TABLE accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, normalized_name text NOT NULL, domain text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(normalized_name, domain));
CREATE TABLE contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid REFERENCES accounts(id), full_name text NOT NULL, normalized_name text NOT NULL, title text, email text, linkedin_url text, identity_resolved boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(account_id,email));
CREATE TABLE prospects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES accounts(id), contact_id uuid REFERENCES contacts(id), category text NOT NULL, owner_key text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(account_id,contact_id,category));
CREATE TABLE import_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_name text NOT NULL, schema_version text NOT NULL, status text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE source_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), import_run_id uuid NOT NULL REFERENCES import_runs(id), row_number integer NOT NULL, source_key text, raw_payload jsonb NOT NULL CHECK(jsonb_typeof(raw_payload)='object'), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(import_run_id,row_number));
CREATE TABLE research_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schema_version text NOT NULL, policy_version text NOT NULL, status text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE research_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), research_run_id uuid NOT NULL REFERENCES research_runs(id), prospect_id uuid NOT NULL REFERENCES prospects(id), question text NOT NULL, target_entity text NOT NULL, source_strategy text NOT NULL, affected_dimensions text[] NOT NULL, stopping_condition text NOT NULL, depth text NOT NULL, max_sources integer NOT NULL CHECK(max_sources>0), max_pages integer NOT NULL CHECK(max_pages>0), permitted_methods text[] NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), research_run_id uuid NOT NULL REFERENCES research_runs(id), normalized_url text NOT NULL, source_class text NOT NULL, title text NOT NULL, retrieved_at timestamptz NOT NULL, published_at timestamptz, content_hash text NOT NULL, supporting_excerpt text NOT NULL, retrieval_status text NOT NULL, bounded_payload jsonb CHECK(bounded_payload IS NULL OR jsonb_typeof(bounded_payload)='object'), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(research_run_id,normalized_url,content_hash));
CREATE TABLE evidence_claims (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES accounts(id), contact_id uuid REFERENCES contacts(id), research_run_id uuid NOT NULL REFERENCES research_runs(id), source_document_id uuid NOT NULL REFERENCES source_documents(id), claim_type text NOT NULL, claim_text text NOT NULL, evidence_state text NOT NULL CHECK(evidence_state IN ('provided','publicly_verified','inferred','unknown','conflicted')), confidence numeric(4,3) NOT NULL CHECK(confidence BETWEEN 0 AND 1), outreach_permission text NOT NULL CHECK(outreach_permission IN ('allowed','hypothesis_only','prohibited')), freshness text NOT NULL, content_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(research_run_id,source_document_id,content_hash,claim_type));
CREATE TABLE evidence_relations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_claim_id uuid NOT NULL REFERENCES evidence_claims(id), to_claim_id uuid NOT NULL REFERENCES evidence_claims(id), relation_type text NOT NULL CHECK(relation_type IN ('corroborates','contradicts')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(from_claim_id,to_claim_id,relation_type), CHECK(from_claim_id<>to_claim_id));
CREATE TABLE reasoning_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), research_run_id uuid NOT NULL REFERENCES research_runs(id), prospect_id uuid NOT NULL REFERENCES prospects(id), step_order integer NOT NULL, step_type text NOT NULL, statement text NOT NULL, confidence numeric(4,3) NOT NULL CHECK(confidence BETWEEN 0 AND 1), assumptions text[] NOT NULL DEFAULT '{}', validation_question text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(research_run_id,prospect_id,step_order));
CREATE TABLE scoring_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), version text NOT NULL UNIQUE, policy_document jsonb NOT NULL CHECK(jsonb_typeof(policy_document)='object'), content_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scorecards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), prospect_id uuid NOT NULL REFERENCES prospects(id), research_run_id uuid NOT NULL REFERENCES research_runs(id), scoring_policy_id uuid NOT NULL REFERENCES scoring_policies(id), fit numeric NOT NULL, urgency numeric NOT NULL, persona numeric NOT NULL, evidence numeric NOT NULL, weighted_total numeric NOT NULL, constrained_total numeric NOT NULL, caps_applied text[] NOT NULL DEFAULT '{}', hard_suppressors text[] NOT NULL DEFAULT '{}', generated_at timestamptz NOT NULL, UNIQUE(prospect_id,research_run_id,scoring_policy_id));
CREATE TABLE prospect_decisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), prospect_id uuid NOT NULL REFERENCES prospects(id), scorecard_id uuid NOT NULL REFERENCES scorecards(id), status prospect_status NOT NULL, confidence numeric(4,3) NOT NULL CHECK(confidence BETWEEN 0 AND 1), rationale text NOT NULL, smallest_next_research_step text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(prospect_id,scorecard_id));
CREATE TABLE customer_stories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_name text NOT NULL, category text NOT NULL, source_url text, proof_text text NOT NULL, content_hash text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sequences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), prospect_decision_id uuid NOT NULL REFERENCES prospect_decisions(id), version integer NOT NULL, goal text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(prospect_decision_id,version));
CREATE TABLE outreach_drafts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sequence_id uuid NOT NULL REFERENCES sequences(id), schema_version text NOT NULL, voice_profile_version text NOT NULL, review_status review_status NOT NULL DEFAULT 'needs_review', subject_line text, email_body text, linkedin_message text, call_opener text, follow_up text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE review_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), outreach_draft_id uuid NOT NULL REFERENCES outreach_drafts(id), review_status review_status NOT NULL, reviewer_action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE action_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), prospect_id uuid NOT NULL REFERENCES prospects(id), action_type text NOT NULL, outcome text, occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE calibration_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_type text NOT NULL, scope text NOT NULL, rule_text text NOT NULL, status text NOT NULL, promoted_by text NOT NULL, supersedes_id uuid REFERENCES calibration_rules(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workflow_preferences (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), preference_key text NOT NULL, preference_value jsonb NOT NULL, version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(preference_key,version));
CREATE TABLE saved_views (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, url_state text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(name));
CREATE TABLE background_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_type text NOT NULL, schema_version text NOT NULL, policy_version text NOT NULL, idempotency_key text NOT NULL UNIQUE, status job_status NOT NULL, progress integer NOT NULL DEFAULT 0 CHECK(progress BETWEEN 0 AND 100), input_artifact_ids uuid[] NOT NULL DEFAULT '{}', output_artifact_ids uuid[] NOT NULL DEFAULT '{}', checkpoint jsonb, errors jsonb, attempts integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, completed_at timestamptz);
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, actor_id text NOT NULL, entity_type text NOT NULL, entity_id uuid, details jsonb NOT NULL CHECK(jsonb_typeof(details)='object'), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE dashboard_exports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), research_run_id uuid NOT NULL REFERENCES research_runs(id), schema_version text NOT NULL, content_hash text NOT NULL, artifact_path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(research_run_id,content_hash));
CREATE FUNCTION reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME; END $$;
CREATE TRIGGER review_events_append_only BEFORE UPDATE OR DELETE ON review_events FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER action_events_append_only BEFORE UPDATE OR DELETE ON action_events FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER audit_events_append_only BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER scoring_policies_immutable BEFORE UPDATE OR DELETE ON scoring_policies FOR EACH ROW EXECUTE FUNCTION reject_mutation();
COMMIT;
